    "original": "ויהי כי זקן יצחק ותכהנה עיניו מראות ויקרא את עשו בנו הגדול ויאמר אליו בני ויאמר אליו הנני",
    "translation": "Diferență reală, confirmată: ויהי כי זקן יצחק ותכהנה עיניו מראות ויקרא את עשו בנו הגדול ויאמר אליו בני ויאמר אליו הנני — „Și a fost, când Isaac îmbătrânise și vederea ochilor săi slăbise, că el l-a chemat pe Esav, fiul său cel mare, și i-a spus: „Fiule!” Și [Esav] i-a spus: „Iată-mă!””",
