    "text": "Și în anul al șaptelea al săptămânii acesteia Isaac l-a chemat pe Esau, fiul său cel mai mare, și i-a zis: Am îmbătrânit, fiule, și iată ochii mei s-au întunecat la vedere, și nu știu ziua morții mele.",
