    "author": "Bekhor Shor (sec. XII)",
    "text": "«Pentru ca sufletul meu să te binecuvânteze înainte de a muri.» Căci darul pe care ți-l voi da nu poate fi contestat de el cu nimic, deoarece legea întâi-născutului nu se aplică la dar; și îți voi da toată stăpânirea, așa cum a spus: „Popoare te vor sluji și neamuri ți se vor prosterna”, căci legea întâi-născutului nu se aplică decât la moștenire; și așa au spus învățătorii noștri: cel care își împarte averea prin cuvânt rostit, a dat mai mult unuia și mai puțin altuia și l-a făcut pe întâi-născut egal cu ei, cuvintele lui rămân în picioare; și de aceea i-a spus să-l binecuvânteze înainte de moartea lui, ca să nu piardă prin ceea ce a vândut dreptul de întâi-născut; și de aceea i-a spus: „Fă-mi mâncăruri gustoase”, căci ai dat dreptul tău de întâi-născut pentru o singură mâncare, iar eu ți-l voi întoarce pentru o masă, și acolo te voi pune stăpân; și încă, felul stăpânitorilor este să facă o masă când primesc stăpânirea, și așa spune: „Și Adonia a jertfit un bou și o vită grasă” etc."
