    "source": "Textul Masoretic (ebraică)",
    "original": "וַתִּקַּח רִבְקָה אֶת־בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדֹל הַחֲמֻדֹת אֲשֶׁר אִתָּהּ בַּבָּיִת וַתַּלְבֵּשׁ אֶת־יַעֲקֹב בְּנָהּ הַקָּטָן",
    "translation": "„Rebeca a luat hainele cele alese ale fiului ei cel mare Esav, care erau la ea în casă, și l-a îmbrăcat pe Iacov, fiul ei cel mic.” — traducerea rabinului Rosen.",
