   {
    "source": "Pentateuhul Samaritean",
    "original": "ותקח רבקה את בגדי עשו בנה הגדול החמדות אשר אתה בבית ותלביש את יעקב בנה הקטן",
    "translation": "Diferență reală, confirmată: ותקח רבקה את בגדי עשו בנה הגדול החמדות אשר אתה בבית ותלביש את יעקב בנה הקטן — „Rebeca a luat hainele cele alese ale fiului ei cel mare Esav, care erau la ea în casă, și l-a îmbrăcat pe Iacov, fiul ei cel mic.”",
    "note": "(Sursă: Schorch, ed. critică 2018, ms. Chester Beatty 751)."
   }
