    "author": "Zohar Chadash, Shir HaShirim 211",
    "text": "A deschis Rabbi Șimon și a zis: este scris (Bereșit 27:27) «și a mirosit mirosul veșmintelor sale și l-a binecuvântat etc.»⁠‌‌​‌‌​‌​​‌​‌‌​‌​​​‌​‌‌‌‌ Ce a văzut Yitzḥak, că deși acea mâncare și băutură i le-a adus Iacov, nu l-a binecuvântat până în vremea în care a mirosit în acele veșminte?",
