    "text": "Dar Cuvântul Domnului a oprit de la el vânatul curat, și a găsit un câine și l-a ucis; și a făcut și el din el mâncăruri și le-a adus tatălui său și a zis tatălui său: „Să se ridice tata și să mănânce din vânatul fiului său, ca să mă binecuvânteze sufletul tău.”"
