    "author": "Or HaChaim (1696–1743)",
    "text": "«De asta a fost numit Iacov, că m-a păcălit de aceste două ori?» Explicația: se miră „oare de aceea i s-a pus numele Iacov?”, iar înțelesul numelui nu arată decât o singură „ʿaqevah”, iar el m-a păcălit („ʿaqavani”) de două ori, căci dacă numele lui ar fi fost „ʿaqevot” sau „ʿoqevot”, l-ar fi păcălit de două ori.<br><br>Sau vrea după acest fel: „oare de aceea i s-a pus numele Iacov” – și nu a spus „ʿaqevah” sau „ʿaqev”, căci atunci nu ar fi arătat decât pe o singură „ʿaqevah”, dar „Iacov” arată continuitate, de aceea până acum deja l-a păcălit („ʿaqavo”) de două ori."
