    "original": "וַיִּשְׂטֹם עֵשָׂו אֶת־יַעֲקֹב עַל־הַבְּרָכָה אֲשֶׁר בֵּרְכוֹ אָבִיו וַיֹּאמֶר עֵשָׂו בְּלִבּוֹ יִקְרְבוּ יְמֵי אֵבֶל אָבִי וְאַהַרְגָה אֶת־יַעֲקֹב אָחִי",
    "translation": "„Esav a prins ură față de Iacov pentru binecuvântarea cu care îl binecuvântase tatăl său și a spus Esav în inima sa: „Se vor apropia zilele de doliu după tatăl meu și-l voi ucide pe fratele meu Iacov.”” — traducerea rabinului Rosen.",
