    "original": "εἶπεν δὲ Ρεβεκκα πρὸς Ισαακ προσώχθικα τῇ ζωῇ μου διὰ τὰς θυγατέρας τῶν υἱῶν Χετ εἰ λήμψεται Ιακωβ γυναῖκα ἀπὸ τῶν θυγατέρων τῆς γῆς ταύτης ἵνα τί μοι ζῆν",
    "greek": true,
    "translation": "",
