    "original": "ותאמר רבקה אל יצחק קצתי בחיי מפני בנות חת אם לקח יעקב אשה מבנות חת כאלה מבנות הארץ למה לי חיים",
    "translation": "Conținutul e identic cu Textul Masoretic la acest verset — fără variante.",
